CREATE TABLE bugs(bug_id VARCHAR, product VARCHAR, component VARCHAR, snapshot_status VARCHAR, snapshot_resolution VARCHAR, opened_at_utc TIMESTAMPTZ, snapshot_as_of_utc TIMESTAMPTZ, source_record_id VARCHAR);
CREATE TABLE sample_membership(bug_id VARCHAR, seed INTEGER);
CREATE TABLE source_records(source_record_id VARCHAR, disposition VARCHAR, normalized_fields JSON, bug_id VARCHAR, source_dataset VARCHAR);
CREATE TABLE bug_links(bug_id VARCHAR, target_bug_id VARCHAR, link_key VARCHAR, relation VARCHAR);
